import * as THREE from 'three/webgpu';
import { texture as textureNode } from 'three/tsl';

export default function createNode(config, ctx) {
  // Extract placement configuration
  const scenePosition = config.scenePosition || [-3.2, -0.3, 0];
  const sceneRotation = config.sceneRotation || [0, 0, 0];
  const sceneScale = config.sceneScale || [1, 1, 1];

  // Create plane geometry
  const geometry = new THREE.PlaneGeometry(1, 1);

  // Load texture from imageUrl
  const imageUrl = config.imageUrl || '/prism-mock/home/nodes/cta-hero-isolated.png';
  const textureMap = ctx.textureLoader.load(imageUrl);
  textureMap.colorSpace = THREE.SRGBColorSpace;

  // Create material with TSL node
  const material = new THREE.MeshBasicNodeMaterial({
    colorNode: textureNode(textureMap),
    transparent: true,
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene placement
  mesh.position.set(...scenePosition);
  mesh.rotation.set(...sceneRotation);
  mesh.scale.set(...sceneScale);

  // Initialize handlers object
  mesh.userData.handlers = {};

  // Setup cleanup function
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    textureMap.dispose();
  };

  return mesh;
}
